    """
def create_figure(
    path: Any,
    caption: Any = None,
    align: Any = None,
    alt: Any = None,
    width: Any = None
) -> object {
    rst = [".. figure:: {}".format(path)];
    if align {
        rst += ["    :align: {}".format(align)];
    }
    if alt {
        rst += ["    :alt: {}".format(alt)];
    }
    if width {
        rst += ["    :width: {}".format(width)];
    }
    if caption {
        rst += [""];
    }
    if caption {
        rst += ["    {}".format(caption)];
    }
    return rst;
}

